create table profiles (
  id uuid primary key references auth.users on delete cascade,
  display_name text not null default '',
  created_at timestamptz not null default now()
);
create function handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into profiles(id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'name', new.raw_user_meta_data->>'full_name', new.email, ''))
  on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();

create table groups (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null unique references profiles on delete cascade,
  name text not null check (char_length(name) between 1 and 50),
  join_code text not null unique,
  late_fee int not null check (late_fee between 0 and 1000000),
  absent_fee int not null check (absent_fee between 0 and 1000000),
  grace_minutes int not null check (grace_minutes between 0 and 120),
  created_at timestamptz not null default now()
);
create table group_members (
  group_id uuid not null references groups on delete cascade,
  user_id uuid not null references profiles on delete cascade,
  role text not null check (role in ('host', 'member')),
  joined_at timestamptz not null default now(),
  primary key (group_id, user_id)
);
create table study_sessions (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references groups on delete cascade,
  starts_at timestamptz not null,
  closed_at timestamptz,
  created_by uuid not null references profiles
);
create index on study_sessions(group_id, starts_at desc);
create table attendance (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references study_sessions on delete cascade,
  user_id uuid not null references profiles on delete cascade,
  status text not null check (status in ('present', 'late', 'absent')),
  checked_at timestamptz not null default now(),
  unique (session_id, user_id)
);
create table fine_entries (
  id bigint generated always as identity primary key,
  group_id uuid not null references groups on delete cascade,
  user_id uuid not null references profiles on delete cascade,
  attendance_id uuid references attendance on delete cascade,
  kind text not null check (kind in ('charge', 'adjust', 'waive', 'payment')),
  amount int not null,
  reason text not null default '' check (char_length(reason) <= 200),
  created_by uuid not null references profiles,
  created_at timestamptz not null default now(),
  check (kind <> 'payment' or amount > 0),
  check ((kind = 'payment') = (attendance_id is null))
);
create index on fine_entries(group_id, user_id);
create index on fine_entries(attendance_id);
create table audit_log (
  id bigint generated always as identity primary key,
  group_id uuid not null references groups on delete cascade,
  actor_id uuid not null references profiles,
  action text not null,
  detail jsonb not null,
  created_at timestamptz not null default now()
);

-- Atomic writers. Amounts are computed by the app (lib/domain/rules.ts); these only store them.
create function create_group(p_owner uuid, p_name text, p_code text, p_late int, p_absent int, p_grace int)
returns uuid language plpgsql as $$
declare gid uuid;
begin
  insert into groups(owner_id, name, join_code, late_fee, absent_fee, grace_minutes)
  values (p_owner, p_name, p_code, p_late, p_absent, p_grace) returning id into gid;
  insert into group_members(group_id, user_id, role) values (gid, p_owner, 'host');
  insert into audit_log(group_id, actor_id, action, detail)
  values (gid, p_owner, 'group.create', jsonb_build_object('name', p_name, 'late_fee', p_late, 'absent_fee', p_absent));
  return gid;
end $$;

create function record_attendance(p_session uuid, p_user uuid, p_status text, p_charge int, p_actor uuid)
returns void language plpgsql as $$
declare gid uuid; aid uuid;
begin
  select group_id into strict gid from study_sessions where id = p_session;
  insert into attendance(session_id, user_id, status) values (p_session, p_user, p_status) returning id into aid;
  if p_charge <> 0 then
    insert into fine_entries(group_id, user_id, attendance_id, kind, amount, created_by)
    values (gid, p_user, aid, 'charge', p_charge, p_actor);
  end if;
  insert into audit_log(group_id, actor_id, action, detail)
  values (gid, p_actor, 'attendance.record', jsonb_build_object('attendance', aid, 'user', p_user, 'status', p_status, 'charge', p_charge));
end $$;

create function add_fine_entry(p_group uuid, p_user uuid, p_attendance uuid, p_kind text, p_amount int,
  p_reason text, p_actor uuid, p_expected int, p_new_status text default null)
returns void language plpgsql as $$
declare cur int; old_status text;
begin
  if p_attendance is not null then
    select status into strict old_status from attendance where id = p_attendance for update;
    select coalesce(sum(amount), 0) into cur from fine_entries where attendance_id = p_attendance;
    if cur <> p_expected then raise exception 'balance changed, retry' using errcode = '40001'; end if;
    if p_new_status is not null then update attendance set status = p_new_status where id = p_attendance; end if;
  end if;
  if p_amount <> 0 then
    insert into fine_entries(group_id, user_id, attendance_id, kind, amount, reason, created_by)
    values (p_group, p_user, p_attendance, p_kind, p_amount, p_reason, p_actor);
  end if;
  insert into audit_log(group_id, actor_id, action, detail)
  values (p_group, p_actor, 'fine.' || p_kind, jsonb_build_object('user', p_user, 'attendance', p_attendance,
    'amount', p_amount, 'reason', p_reason, 'old_status', old_status, 'new_status', p_new_status));
end $$;

revoke execute on function create_group, record_attendance, add_fine_entry from public, anon, authenticated;
grant execute on function create_group, record_attendance, add_fine_entry to service_role;

-- Row-level security: members may read their group; nobody but service_role may write.
create function is_member(g uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from group_members where group_id = g and user_id = auth.uid()) $$;
create function is_host(g uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from group_members where group_id = g and user_id = auth.uid() and role = 'host') $$;

alter table profiles enable row level security;
alter table groups enable row level security;
alter table group_members enable row level security;
alter table study_sessions enable row level security;
alter table attendance enable row level security;
alter table fine_entries enable row level security;
alter table audit_log enable row level security;

create policy read_profiles on profiles for select using (
  id = auth.uid() or exists (select 1 from group_members m where m.user_id = profiles.id and is_member(m.group_id)));
create policy read_groups on groups for select using (is_member(id));
create policy read_members on group_members for select using (is_member(group_id));
create policy read_sessions on study_sessions for select using (is_member(group_id));
create policy read_attendance on attendance for select using (
  exists (select 1 from study_sessions s where s.id = session_id and is_member(s.group_id)));
create policy read_fines on fine_entries for select using (is_member(group_id));
create policy read_audit on audit_log for select using (is_host(group_id));

