import { NextResponse } from 'next/server';
import { env, userClient } from '@/lib/services/supabase';

export async function GET(req: Request) {
  const code = new URL(req.url).searchParams.get('code');
  const site = env('NEXT_PUBLIC_SITE_URL');
  if (!code) return NextResponse.redirect(`${site}/?error=login`);
  const { error } = await (await userClient()).auth.exchangeCodeForSession(code);
  if (error) { console.error(error); return NextResponse.redirect(`${site}/?error=login`); }
  return NextResponse.redirect(site);
}

