  const groupId = att.study_sessions.group_id;
  await requireRole(groupId, user.id, 'host');
  const current = attendanceBalance(await ledger(groupId, att.user_id), att.id);
  const delta = deltaTo(current, input.action === 'waive' ? 0 : input.amount!);
  await rpc('add_fine_entry', { p_group: groupId, p_user: att.user_id, p_attendance: att.id, p_kind: input.action,
    p_amount: delta, p_reason: input.reason, p_actor: user.id, p_expected: current });
});

