import { paymentInput } from '@/lib/domain/inputs';
import { checkPayment, summarize } from '@/lib/domain/rules';
import { requireRole, requireUser, route } from '@/lib/http';
import { ledger, roleOf, rpc } from '@/lib/services/repo';
import { HttpError } from '@/lib/errors';

export const POST = route(async (body) => {
  const user = await requireUser();
  const { groupId, userId, amount } = paymentInput.parse(body);
  await requireRole(groupId, user.id, 'host');
  if (!(await roleOf(groupId, userId))) throw new HttpError(404, '모임 멤버가 아닙니다');
  const [summary] = summarize(await ledger(groupId, userId), [userId]);
  checkPayment(summary.outstanding, amount);
  await rpc('add_fine_entry', { p_group: groupId, p_user: userId, p_attendance: null, p_kind: 'payment',
    p_amount: amount, p_reason: '납부 기록', p_actor: user.id, p_expected: 0 });
});

