import { notFound, redirect } from 'next/navigation';
import { ApiForm } from '@/components/ApiForm';
import { attendanceBalance, summarize, type LedgerEntry } from '@/lib/domain/rules';
import { userClient } from '@/lib/services/supabase';

const KST = (iso: string) => new Date(iso).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' });
const STATUS = { present: '출석', late: '지각', absent: '결석' } as const;

export default async function GroupPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const sb = await userClient();
  const { data: { user } } = await sb.auth.getUser();
  if (!user) redirect('/?expired=1');
  // RLS limits every read below to groups the user belongs to.
  const [g, m, s, f] = await Promise.all([
    sb.from('groups').select('name, join_code, late_fee, absent_fee, grace_minutes').eq('id', id).maybeSingle(),
    sb.from('group_members').select('user_id, role, profiles(display_name)').eq('group_id', id),
    sb.from('study_sessions').select('id, starts_at, closed_at, attendance(id, user_id, status)').eq('group_id', id).order('starts_at', { ascending: false }).limit(20),
    sb.from('fine_entries').select('user_id, attendance_id, kind, amount').eq('group_id', id),
  ]);
  for (const r of [g, m, s, f]) if (r.error) throw new Error(r.error.message);
  if (!g.data) notFound();
  const members = (m.data ?? []) as unknown as { user_id: string; role: string; profiles: { display_name: string } }[];
  const sessions = (s.data ?? []) as { id: string; starts_at: string; closed_at: string | null; attendance: { id: string; user_id: string; status: keyof typeof STATUS }[] }[];
  const entries: LedgerEntry[] = (f.data ?? []).map((e) => ({ userId: e.user_id, attendanceId: e.attendance_id, kind: e.kind, amount: e.amount }));
  const isHost = members.some((x) => x.user_id === user.id && x.role === 'host');
  const nameOf = (uid: string) => members.find((x) => x.user_id === uid)?.profiles.display_name || '이름 없음';
  const summary = summarize(entries, members.map((x) => x.user_id));

  return (
    <main className="space-y-6">
      <h1 className="text-xl font-bold">{g.data.name}</h1>
      <p className="text-sm text-zinc-600">지각 {g.data.late_fee}원 · 결석 {g.data.absent_fee}원 · 유예 {g.data.grace_minutes}분 · 참여 코드 <code>{g.data.join_code}</code></p>

      <section><h2 className="font-semibold">벌금 정산</h2>
        <table className="w-full text-sm"><thead><tr className="text-left"><th>멤버</th><th>누적</th><th>납부</th><th>미납</th><th>상태</th></tr></thead>
          <tbody>{summary.map((r) => (
            <tr key={r.userId} className="border-t"><td>{nameOf(r.userId)}</td><td>{r.fined}</td><td>{r.paid}</td><td>{r.outstanding}</td>
              <td>{r.paidUp ? '완납' : '미납'}{isHost && !r.paidUp && <ApiForm action="/api/payments" label="납부 기록" hidden={{ groupId: id, userId: r.userId }} fields={[{ name: 'amount', label: '금액', type: 'number' }]} />}</td></tr>
          ))}</tbody></table>
      </section>

      {isHost && <section><h2 className="font-semibold">출석 일정 만들기</h2>
        <ApiForm action="/api/sessions" label="만들기" hidden={{ groupId: id }} fields={[{ name: 'startsAt', label: '시작 시각', type: 'datetime-local' }]} />
      </section>}

      <section className="space-y-3"><h2 className="font-semibold">출석</h2>
        {sessions.map((ss) => (
          <div key={ss.id} className="rounded border bg-white p-3">
            <p className="font-medium">{KST(ss.starts_at)} {ss.closed_at && '(마감)'}</p>
            {!ss.closed_at && <ApiForm action="/api/checkin" label="출석 체크" hidden={{ sessionId: ss.id }} />}
            {isHost && !ss.closed_at && <ApiForm action="/api/sessions/close" label="마감(미출석자 결석 처리)" hidden={{ sessionId: ss.id }} />}
            <ul className="mt-2 space-y-2 text-sm">{ss.attendance.map((a) => (
              <li key={a.id}>{nameOf(a.user_id)} · {STATUS[a.status]} · 벌금 {attendanceBalance(entries, a.id)}원
                {isHost && <div className="mt-1 space-y-1 pl-3">
                  <ApiForm action="/api/attendance" label="상태 변경" hidden={{ attendanceId: a.id }} fields={[{ name: 'status', label: '상태', options: ['present', 'late', 'absent'] }]} />
                  <ApiForm action="/api/fines" label="금액 수정" hidden={{ attendanceId: a.id, action: 'adjust' }} fields={[{ name: 'amount', label: '금액', type: 'number' }, { name: 'reason', label: '사유' }]} />
                  <ApiForm action="/api/fines" label="면제" hidden={{ attendanceId: a.id, action: 'waive' }} fields={[{ name: 'reason', label: '사유' }]} />
                </div>}
              </li>))}</ul>
          </div>
        ))}
      </section>
    </main>
  );
}

